package ru.neverland.townyresearch.command;
import com.palmergames.bukkit.towny.TownyAPI;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import ru.neverland.townyresearch.NeverLandTownyResearch;
import ru.neverland.townyresearch.gui.ResearchMenu;
import ru.neverland.townyresearch.service.*;
import java.util.*;
public final class ResearchCommand implements CommandExecutor,TabCompleter {
    private final NeverLandTownyResearch plugin;private final ResearchService service;private final ResearchMenu menu;private final ru.neverland.townyresearch.licenses.LicenseMenu licenses;
    public ResearchCommand(NeverLandTownyResearch plugin,ResearchService service,ResearchMenu menu){this.plugin=plugin;this.service=service;this.menu=menu;licenses=new ru.neverland.townyresearch.licenses.LicenseMenu(plugin,service);plugin.getServer().getPluginManager().registerEvents(licenses,plugin);}
    private void count(String[] a,int n,String usage){if(a.length!=n)throw new IllegalArgumentException(usage);}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyResearch")){return true;}try{execute(sender,args);}catch(Exception ex){Ui.tell(sender,"&c"+(ex.getMessage()==null?"Операция не завершена; проверьте консоль":ex.getMessage()));if(!(ex instanceof IllegalArgumentException||ex instanceof IllegalStateException))plugin.getLogger().log(java.util.logging.Level.WARNING,"Ошибка команды исследований",ex);}return true;} }
    private void execute(CommandSender sender,String[] args)throws Exception{String action=args.length==0?"menu":args[0].toLowerCase(Locale.ROOT);
        if(action.equals("license")){license(sender,args);return;}
        if(action.equals("reload")||action.equals("town")){if(!sender.hasPermission("neverlandtownyresearch.admin"))throw new IllegalArgumentException("Недостаточно прав");if(action.equals("reload")){count(args,1,"/townyresearch reload");plugin.reloadResearch().whenComplete((ok,error)->{if(sender instanceof Player p){if(plugin.isEnabled())ru.neverland.core.SuiteScheduler.entity(plugin,p,()->{if(p.isOnline())Ui.tell(p,Boolean.TRUE.equals(ok)?"Настройки исследований обновлены.":"Настройки не применены; проверьте консоль.");});}else plugin.getLogger().info(Boolean.TRUE.equals(ok)?"Настройки исследований обновлены.":"Настройки не применены; проверьте консоль.");});Ui.tell(sender,"Проверяем настройки исследований…");}else{count(args,2,"/townyresearch town <город>");if(!(sender instanceof Player player))throw new IllegalArgumentException("Меню доступно в игре");var town=TownyAPI.getInstance().getTown(args[1]);if(town==null)throw new IllegalArgumentException("Город не найден");menu.open(player,town.getUUID(),null);}return;}
        if(!(sender instanceof Player player))throw new IllegalArgumentException("Консоль: /townyresearch reload");if(!player.hasPermission("neverlandtownyresearch.use"))throw new IllegalArgumentException("Недостаточно прав");var town=service.town(player);if(town==null)throw new IllegalArgumentException("Вы не состоите в городе");
        switch(action){case "menu"->{count(args,args.length==0?0:1,"/t research");menu.open(player,town.getUUID(),null);}case "info"->{count(args,2,"/t research info <технология>");menu.open(player,town.getUUID(),args[1]);}
            case "start","cancel"->{count(args,action.equals("start")?2:1,"/t research "+action+(action.equals("start")?" <технология>":""));if(!service.manager(player,town))throw new IllegalArgumentException("Нужны права мэра, помощника или управляющего");if(action.equals("start")){service.begin(town.getUUID(),args[1]);Ui.tell(player,"Исследование добавлено. При нехватке свободных знаний оно будет ждать пополнения.");}else{service.cancel(town.getUUID());Ui.tell(player,"Отмена сохранена; зарезервированные знания возвращаются в город.");}menu.open(player,town.getUUID(),null);}
            case "help"->Ui.tell(player,"/t research — технологии; info <технология> — требования; start <технология> — поставить в изучение; cancel — отменить с возвратом знаний. Одновременно изучается одна технология.");default->throw new IllegalArgumentException("Справка: /t research help");}
    }
    private void license(CommandSender sender,String[] args)throws Exception{
        String action=args.length<2?"menu":args[1].toLowerCase(Locale.ROOT);
        if(action.equals("resolve")){if(!sender.isOp()&&!sender.hasPermission("neverlandtownyresearch.admin"))throw new IllegalArgumentException("Нужны права администратора");if(args.length!=5||!Set.of("paid","unpaid").contains(args[3])||!args[4].equals("confirm"))throw new IllegalArgumentException("После точной сверки банковского журнала: /townyresearch license resolve <UUID> paid|unpaid confirm");UUID id=UUID.fromString(args[2]);service.licenses().resolve(id,args[3].equals("paid"),sender).whenComplete((row,error)->{if(sender instanceof Player p){if(plugin.isEnabled())ru.neverland.core.SuiteScheduler.entity(plugin,p,()->{if(p.isOnline()&&(p.isOp()||p.hasPermission("neverlandtownyresearch.admin")))Ui.tell(p,error==null?"Сверка лицензии сохранена. Выплата не повторялась.":"Сверка пока не сохранена; обновите лицензию.");});}else plugin.getLogger().info(error==null?"Сверка лицензии "+id+" сохранена":"Сверка лицензии "+id+" не завершена");});return;}
        if(!(sender instanceof Player player))throw new IllegalArgumentException("Меню лицензий доступно в игре");if(!player.hasPermission("neverlandtownyresearch.use")||!player.hasPermission("neverlandtownyresearch.licenses"))throw new IllegalArgumentException("Нет доступа к лицензиям");
        if(action.equals("menu")){licenses.open(player,0);return;}if(action.equals("show")){count(args,3,"/t research license show <UUID>");licenses.details(player,UUID.fromString(args[2]),0,null);return;}
        if(action.equals("offer")){count(args,7,"/t research license offer <город> <технология> <уровень> <монеты> <часы>");var buyer=TownyAPI.getInstance().getTown(args[2]);if(buyer==null)throw new IllegalArgumentException("Город-покупатель не найден");long cents=new java.math.BigDecimal(args[5].replace(',','.')).movePointRight(2).longValueExact();service.licenses().offer(player,buyer.getUUID(),args[3],Integer.parseInt(args[4]),cents,Integer.parseInt(args[6])).whenComplete((row,error)->{if(plugin.isEnabled())ru.neverland.core.SuiteScheduler.entity(plugin,player,()->{if(!player.isOnline())return;Ui.tell(player,error==null?"Предложение сохранено; управляющий другого города может открыть лицензии и подтвердить его.":"Предложение пока не сохранено; обновите меню.");licenses.open(player,0);});});Ui.tell(player,"Сохраняем предложение технологии…");return;}
        throw new IllegalArgumentException("/t research license [offer <город> <технология> <уровень> <монеты> <часы>|show <UUID>]");
    }
    @Override public List<String> onTabComplete(CommandSender sender,Command command,String alias,String[] args){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {var result=new ArrayList<String>();if(args.length==1){if(sender.hasPermission("neverlandtownyresearch.use"))result.addAll(List.of("menu","info","start","cancel","help","license"));if(sender.hasPermission("neverlandtownyresearch.admin"))result.addAll(List.of("reload","town"));}else if(args.length==2&&args[0].equals("license")){result.addAll(List.of("offer","show"));if(sender.isOp()||sender.hasPermission("neverlandtownyresearch.admin"))result.add("resolve");}else if(args.length==3&&args[0].equals("license")&&args[1].equals("offer"))TownyAPI.getInstance().getTowns().forEach(t->result.add(t.getName()));else if(args.length==4&&args[0].equals("license")&&args[1].equals("offer"))result.addAll(service.settings().technologies().keySet());else if(args.length==2&&Set.of("start","info").contains(args[0])&&sender.hasPermission("neverlandtownyresearch.use"))result.addAll(service.settings().technologies().keySet());else if(args.length==2&&args[0].equals("town")&&sender.hasPermission("neverlandtownyresearch.admin"))TownyAPI.getInstance().getTowns().forEach(t->result.add(t.getName()));String prefix=args.length==0?"":args[args.length-1].toLowerCase(Locale.ROOT);return result.stream().filter(s->s.toLowerCase(Locale.ROOT).startsWith(prefix)).sorted().toList();} }
}
